    CASE WHEN lower(trim(`deletion_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`deletion_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `deletion_flag`,
    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`effective_until`), 'yyyy-MM-dd'), try_to_date(trim(`effective_until`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_until`) AS DATE)) AS `effective_until`,
    CASE WHEN lower(trim(`gmp_compliant`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliant`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliant`,
    CASE WHEN lower(trim(`is_configurable`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_configurable`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_configurable`,
    CASE WHEN lower(trim(`is_phantom`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_phantom`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_phantom`,
    NULLIF(trim(`last_changed_by`), '') AS `last_changed_by`,
    COALESCE(try_to_timestamp(trim(`last_changed_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_changed_timestamp`) AS TIMESTAMP)) AS `last_changed_timestamp`,
    TRY_CAST(NULLIF(trim(`lot_size_from`), '') AS DECIMAL(18,3)) AS `lot_size_from`,
    TRY_CAST(NULLIF(trim(`lot_size_to`), '') AS DECIMAL(18,3)) AS `lot_size_to`,
    NULLIF(trim(`lot_size_uom`), '') AS `lot_size_uom`,
    NULLIF(trim(`material_number`), '') AS `material_number`,
    CASE WHEN lower(trim(`mrp_relevance`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`mrp_relevance`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `mrp_relevance`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    CASE lower(trim(`plm_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'in_review' THEN 'in_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'active' THEN 'active'
      WHEN 'obsolete' THEN 'obsolete'
      WHEN 'superseded' THEN 'superseded'
      ELSE NULLIF(trim(`plm_status`), '')
    END AS `plm_status`,
    NULLIF(trim(`production_version`), '') AS `production_version`,
    CASE WHEN lower(trim(`reach_compliant`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`reach_compliant`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `reach_compliant`,
    CASE lower(trim(`regulatory_approval_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'conditionally_approved' THEN 'conditionally_approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'not_required' THEN 'not_required'
      ELSE NULLIF(trim(`regulatory_approval_status`), '')
    END AS `regulatory_approval_status`,
    CASE WHEN lower(trim(`rspo_certified`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`rspo_certified`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `rspo_certified`,
    NULLIF(trim(`source_system_bom_code`), '') AS `source_system_bom_code`,
    NULLIF(trim(`version`), '') AS `version`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_product_bom
)
SELECT *
FROM typed
QUALIFY `product_bom_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `product_bom_id` ORDER BY _ingested_at DESC) = 1;

-- product.bom_line ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_bom_line (
  CONSTRAINT `bom_line_id_not_null` EXPECT (`bom_line_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.bom_line typed and cleaned, one row per bom_line_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`bom_line_id`), '') AS BIGINT) AS `bom_line_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`product_bom_id`), '') AS BIGINT) AS `product_bom_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    NULLIF(trim(`alternative_item_group`), '') AS `alternative_item_group`,
    TRY_CAST(NULLIF(trim(`alternative_priority`), '') AS INT) AS `alternative_priority`,
    CASE lower(trim(`bom_item_category`))
      WHEN 'stock' THEN 'stock'
      WHEN 'non_stock' THEN 'non_stock'
      WHEN 'variable_size' THEN 'variable_size'
      WHEN 'document' THEN 'document'
      WHEN 'text' THEN 'text'
      WHEN 'class' THEN 'class'
      ELSE NULLIF(trim(`bom_item_category`), '')
    END AS `bom_item_category`,
    CASE WHEN lower(trim(`bulk_material_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`bulk_material_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `bulk_material_flag`,
    NULLIF(trim(`change_number`), '') AS `change_number`,
    CASE WHEN lower(trim(`co_product_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`co_product_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `co_product_flag`,
    TRY_CAST(NULLIF(trim(`component_cost_usd`), '') AS DECIMAL(18,4)) AS `component_cost_usd`,
    NULLIF(trim(`component_item_number`), '') AS `component_item_number`,
    CASE lower(trim(`component_type`))
      WHEN 'raw_material' THEN 'raw_material'
      WHEN 'packaging' THEN 'packaging'
      WHEN 'semi_finished' THEN 'semi_finished'
      WHEN 'finished_good' THEN 'finished_good'
      WHEN 'co_product' THEN 'co_product'
      WHEN 'by_product' THEN 'by_product'
      ELSE NULLIF(trim(`component_type`), '')
    END AS `component_type`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    CASE WHEN lower(trim(`fixed_quantity_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`fixed_quantity_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `fixed_quantity_flag`,
    CASE WHEN lower(trim(`hazardous_material_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazardous_material_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazardous_material_flag`,
    NULLIF(trim(`inci_name`), '') AS `inci_name`,
    CASE WHEN lower(trim(`is_alternative_item`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_alternative_item`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_alternative_item`,
    CASE WHEN lower(trim(`is_critical_component`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_critical_component`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_critical_component`,
    CASE lower(trim(`issue_method`))
      WHEN 'backflush' THEN 'backflush'
      WHEN 'manual' THEN 'manual'
      WHEN 'pick_list' THEN 'pick_list'
      WHEN 'kanban' THEN 'kanban'
      ELSE NULLIF(trim(`issue_method`), '')
    END AS `issue_method`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_offset_days`), '') AS INT) AS `lead_time_offset_days`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    CASE lower(trim(`line_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending_approval' THEN 'pending_approval'
      WHEN 'obsolete' THEN 'obsolete'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`line_status`), '')
    END AS `line_status`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(18,4)) AS `minimum_order_quantity`,
    TRY_CAST(NULLIF(trim(`operation_number`), '') AS BIGINT) AS `operation_number`,
    CASE WHEN lower(trim(`phantom_item_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`phantom_item_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `phantom_item_flag`,
    NULLIF(trim(`reach_registration_number`), '') AS `reach_registration_number`,
    CASE WHEN lower(trim(`recursive_bom_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`recursive_bom_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `recursive_bom_flag`,
    TRY_CAST(NULLIF(trim(`required_quantity`), '') AS DECIMAL(18,6)) AS `required_quantity`,
    TRY_CAST(NULLIF(trim(`scrap_percentage`), '') AS DECIMAL(7,4)) AS `scrap_percentage`,
    NULLIF(trim(`sds_document_number`), '') AS `sds_document_number`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    NULLIF(trim(`storage_location`), '') AS `storage_location`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`usage_probability_pct`), '') AS DECIMAL(7,4)) AS `usage_probability_pct`,
    COALESCE(try_to_date(trim(`valid_from_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_from_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_from_date`) AS DATE)) AS `valid_from_date`,
    COALESCE(try_to_date(trim(`valid_to_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_to_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_to_date`) AS DATE)) AS `valid_to_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_bom_line
)
SELECT *
FROM typed
QUALIFY `bom_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `bom_line_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- product.formulation ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_formulation (
  CONSTRAINT `formulation_id_not_null` EXPECT (`formulation_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.formulation typed and cleaned, one row per formulation_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`formulation_id`), '') AS BIGINT) AS `formulation_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    NULLIF(trim(`active_ingredient_name`), '') AS `active_ingredient_name`,
    TRY_CAST(NULLIF(trim(`active_ingredient_pct`), '') AS DECIMAL(6,3)) AS `active_ingredient_pct`,
    NULLIF(trim(`allergen_declaration`), '') AS `allergen_declaration`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    NULLIF(trim(`bom_reference_code`), '') AS `bom_reference_code`,
    NULLIF(trim(`code`), '') AS `code`,
    NULLIF(trim(`color_description`), '') AS `color_description`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    COALESCE(try_to_date(trim(`effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_date`) AS DATE)) AS `effective_date`,
    NULLIF(trim(`formulation_type`), '') AS `formulation_type`,
    NULLIF(trim(`fragrance_code`), '') AS `fragrance_code`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    NULLIF(trim(`inci_declaration`), '') AS `inci_declaration`,
    NULLIF(trim(`intended_use`), '') AS `intended_use`,
    CASE WHEN lower(trim(`is_cruelty_free`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_cruelty_free`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_cruelty_free`,
    CASE WHEN lower(trim(`is_fragrance_free`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_fragrance_free`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_fragrance_free`,
    CASE WHEN lower(trim(`is_vegan`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_vegan`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_vegan`,
    NULLIF(trim(`lab_notebook_reference`), '') AS `lab_notebook_reference`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    CASE lower(trim(`lifecycle_stage`))
      WHEN 'lab_development' THEN 'lab_development'
      WHEN 'pilot' THEN 'pilot'
      WHEN 'stability_testing' THEN 'stability_testing'
      WHEN 'regulatory_review' THEN 'regulatory_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'obsolete' THEN 'obsolete'
      ELSE NULLIF(trim(`lifecycle_stage`), '')
    END AS `lifecycle_stage`,
    NULLIF(trim(`name`), '') AS `name`,
    COALESCE(try_to_date(trim(`obsolescence_date`), 'yyyy-MM-dd'), try_to_date(trim(`obsolescence_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`obsolescence_date`) AS DATE)) AS `obsolescence_date`,
    TRY_CAST(NULLIF(trim(`ph_max`), '') AS DECIMAL(5,2)) AS `ph_max`,
    TRY_CAST(NULLIF(trim(`ph_min`), '') AS DECIMAL(5,2)) AS `ph_min`,
    NULLIF(trim(`preservative_system`), '') AS `preservative_system`,
    NULLIF(trim(`rd_project_code`), '') AS `rd_project_code`,
    NULLIF(trim(`reach_registration_number`), '') AS `reach_registration_number`,
    CASE lower(trim(`regulatory_approval_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'conditionally_approved' THEN 'conditionally_approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'withdrawn' THEN 'withdrawn'
      ELSE NULLIF(trim(`regulatory_approval_status`), '')
    END AS `regulatory_approval_status`,
    CASE lower(trim(`regulatory_classification`))
      WHEN 'cosmetic' THEN 'cosmetic'
      WHEN 'otc_drug' THEN 'otc_drug'
      WHEN 'household_chemical' THEN 'household_chemical'
      WHEN 'biocide' THEN 'biocide'
      WHEN 'medical_device' THEN 'medical_device'
      WHEN 'food_contact' THEN 'food_contact'
      ELSE NULLIF(trim(`regulatory_classification`), '')
    END AS `regulatory_classification`,
    CASE WHEN lower(trim(`rspo_certified`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`rspo_certified`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `rspo_certified`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    TRY_CAST(NULLIF(trim(`stability_period_months`), '') AS INT) AS `stability_period_months`,
    NULLIF(trim(`storage_condition`), '') AS `storage_condition`,
    TRY_CAST(NULLIF(trim(`total_solid_content_pct`), '') AS DECIMAL(6,3)) AS `total_solid_content_pct`,
    NULLIF(trim(`version_number`), '') AS `version_number`,
    TRY_CAST(NULLIF(trim(`viscosity_max_cps`), '') AS DECIMAL(10,2)) AS `viscosity_max_cps`,
    TRY_CAST(NULLIF(trim(`viscosity_min_cps`), '') AS DECIMAL(10,2)) AS `viscosity_min_cps`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_formulation
)
SELECT *
FROM typed
QUALIFY `formulation_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `formulation_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- product.formulation_ingredient ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_formulation_ingredient (
  CONSTRAINT `formulation_ingredient_id_not_null` EXPECT (`formulation_ingredient_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.formulation_ingredient typed and cleaned, one row per formulation_ingredient_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`formulation_ingredient_id`), '') AS BIGINT) AS `formulation_ingredient_id`,
    TRY_CAST(NULLIF(trim(`formulation_id`), '') AS BIGINT) AS `formulation_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    NULLIF(trim(`allergen_declaration`), '') AS `allergen_declaration`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_timestamp(trim(`approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approved_timestamp`) AS TIMESTAMP)) AS `approved_timestamp`,
    NULLIF(trim(`cas_number`), '') AS `cas_number`,
    TRY_CAST(NULLIF(trim(`concentration_max_pct`), '') AS DECIMAL(10,6)) AS `concentration_max_pct`,
    TRY_CAST(NULLIF(trim(`concentration_min_pct`), '') AS DECIMAL(10,6)) AS `concentration_min_pct`,
    TRY_CAST(NULLIF(trim(`concentration_nominal_pct`), '') AS DECIMAL(10,6)) AS `concentration_nominal_pct`,
    CASE lower(trim(`concentration_uom`))
      WHEN '% w/w' THEN '% w/w'
      WHEN '% v/v' THEN '% v/v'
      WHEN '% w/v' THEN '% w/v'
      WHEN 'ppm' THEN 'ppm'
      WHEN 'ppb' THEN 'ppb'
      WHEN 'mg/kg' THEN 'mg/kg'
      ELSE NULLIF(trim(`concentration_uom`), '')
    END AS `concentration_uom`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`ec_number`), '') AS `ec_number`,
    COALESCE(try_to_date(trim(`effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_date`) AS DATE)) AS `effective_date`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    CASE lower(trim(`fda_status`))
      WHEN 'approved' THEN 'approved'
      WHEN 'gras' THEN 'gras'
      WHEN 'permitted' THEN 'permitted'
      WHEN 'restricted' THEN 'restricted'
      WHEN 'prohibited' THEN 'prohibited'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`fda_status`), '')
    END AS `fda_status`,
    NULLIF(trim(`ghs_hazard_classification`), '') AS `ghs_hazard_classification`,
    NULLIF(trim(`grade_specification`), '') AS `grade_specification`,
    CASE lower(trim(`halal_status`))
      WHEN 'certified' THEN 'certified'
      WHEN 'not_certified' THEN 'not_certified'
      WHEN 'not_applicable' THEN 'not_applicable'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`halal_status`), '')
    END AS `halal_status`,
    CASE lower(trim(`ifra_compliance_status`))
      WHEN 'compliant' THEN 'compliant'
      WHEN 'non_compliant' THEN 'non_compliant'
      WHEN 'not_applicable' THEN 'not_applicable'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`ifra_compliance_status`), '')
    END AS `ifra_compliance_status`,
    NULLIF(trim(`inci_name`), '') AS `inci_name`,
    NULLIF(trim(`ingredient_function`), '') AS `ingredient_function`,
    NULLIF(trim(`ingredient_name`), '') AS `ingredient_name`,
    CASE lower(trim(`ingredient_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'phased_out' THEN 'phased_out'
      ELSE NULLIF(trim(`ingredient_status`), '')
    END AS `ingredient_status`,
    CASE WHEN lower(trim(`is_active_ingredient`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_active_ingredient`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_active_ingredient`,
    CASE WHEN lower(trim(`is_fragrance_allergen`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_fragrance_allergen`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_fragrance_allergen`,
    CASE WHEN lower(trim(`is_natural_origin`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_natural_origin`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_natural_origin`,
    CASE WHEN lower(trim(`is_palm_derived`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_palm_derived`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_palm_derived`,
    CASE WHEN lower(trim(`is_prohibited_substance`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_prohibited_substance`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_prohibited_substance`,
    CASE WHEN lower(trim(`is_restricted_substance`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_restricted_substance`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_restricted_substance`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    TRY_CAST(NULLIF(trim(`natural_origin_index`), '') AS DECIMAL(5,4)) AS `natural_origin_index`,
    NULLIF(trim(`origin_country_code`), '') AS `origin_country_code`,
    NULLIF(trim(`physical_form`), '') AS `physical_form`,
    NULLIF(trim(`reach_registration_number`), '') AS `reach_registration_number`,
    CASE lower(trim(`reach_registration_status`))
      WHEN 'registered' THEN 'registered'
      WHEN 'pre-registered' THEN 'pre-registered'
      WHEN 'exempt' THEN 'exempt'
      WHEN 'not_required' THEN 'not_required'
      WHEN 'pending' THEN 'pending'
      WHEN 'failed' THEN 'failed'
      ELSE NULLIF(trim(`reach_registration_status`), '')
    END AS `reach_registration_status`,
    NULLIF(trim(`regulatory_limit_reference`), '') AS `regulatory_limit_reference`,
    TRY_CAST(NULLIF(trim(`regulatory_max_concentration_pct`), '') AS DECIMAL(10,6)) AS `regulatory_max_concentration_pct`,
    NULLIF(trim(`sds_reference_number`), '') AS `sds_reference_number`,
    NULLIF(trim(`sds_version`), '') AS `sds_version`,
    NULLIF(trim(`supplier_material_code`), '') AS `supplier_material_code`,
    CASE WHEN lower(trim(`svhc_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`svhc_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `svhc_flag`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    CASE lower(trim(`vegan_status`))
      WHEN 'vegan' THEN 'vegan'
      WHEN 'non_vegan' THEN 'non_vegan'
      WHEN 'unknown' THEN 'unknown'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`vegan_status`), '')
    END AS `vegan_status`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_formulation_ingredient
)
SELECT *
FROM typed
QUALIFY `formulation_ingredient_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `formulation_ingredient_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- product.packaging_spec ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_packaging_spec (
  CONSTRAINT `packaging_spec_id_not_null` EXPECT (`packaging_spec_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.packaging_spec typed and cleaned, one row per packaging_spec_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`packaging_spec_id`), '') AS BIGINT) AS `packaging_spec_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`material_id`), '') AS BIGINT) AS `material_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    CASE lower(trim(`approval_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'under_review' THEN 'under_review'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    NULLIF(trim(`artwork_ref`), '') AS `artwork_ref`,
    NULLIF(trim(`color`), '') AS `color`,
    NULLIF(trim(`component_type`), '') AS `component_type`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`ean`), '') AS `ean`,
    COALESCE(try_to_date(trim(`effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_date`) AS DATE)) AS `effective_date`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`finish`), '') AS `finish`,
    TRY_CAST(NULLIF(trim(`gross_weight_g`), '') AS DECIMAL(12,3)) AS `gross_weight_g`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    TRY_CAST(NULLIF(trim(`height_mm`), '') AS DECIMAL(10,3)) AS `height_mm`,
    TRY_CAST(NULLIF(trim(`hi`), '') AS INT) AS `hi`,
    CASE WHEN lower(trim(`is_fsc_certified`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_fsc_certified`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_fsc_certified`,
    CASE WHEN lower(trim(`is_rspo_certified`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_rspo_certified`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_rspo_certified`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_days`), '') AS INT) AS `lead_time_days`,
    TRY_CAST(NULLIF(trim(`length_mm`), '') AS DECIMAL(10,3)) AS `length_mm`,
    CASE lower(trim(`lifecycle_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'active' THEN 'active'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'obsolete' THEN 'obsolete'
      WHEN 'discontinued' THEN 'discontinued'
      ELSE NULLIF(trim(`lifecycle_status`), '')
    END AS `lifecycle_status`,
    TRY_CAST(NULLIF(trim(`moq`), '') AS INT) AS `moq`,
    CASE lower(trim(`packaging_level`))
      WHEN 'primary' THEN 'primary'
      WHEN 'secondary' THEN 'secondary'
      WHEN 'tertiary' THEN 'tertiary'
      WHEN 'display_unit' THEN 'display_unit'
      WHEN 'pallet' THEN 'pallet'
      ELSE NULLIF(trim(`packaging_level`), '')
    END AS `packaging_level`,
    TRY_CAST(NULLIF(trim(`pcr_content_pct`), '') AS DECIMAL(5,2)) AS `pcr_content_pct`,
    NULLIF(trim(`print_method`), '') AS `print_method`,
    TRY_CAST(NULLIF(trim(`qty_per_parent`), '') AS INT) AS `qty_per_parent`,
    NULLIF(trim(`recyclability_code`), '') AS `recyclability_code`,
    CASE WHEN lower(trim(`regulatory_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_compliance_flag`,
    NULLIF(trim(`spec_code`), '') AS `spec_code`,
    NULLIF(trim(`spec_name`), '') AS `spec_name`,
    NULLIF(trim(`supplier_tooling_ref`), '') AS `supplier_tooling_ref`,
    TRY_CAST(NULLIF(trim(`tare_weight_g`), '') AS DECIMAL(12,3)) AS `tare_weight_g`,
    TRY_CAST(NULLIF(trim(`ti`), '') AS INT) AS `ti`,
    TRY_CAST(NULLIF(trim(`unit_cost`), '') AS DECIMAL(18,6)) AS `unit_cost`,
    NULLIF(trim(`upc`), '') AS `upc`,
    NULLIF(trim(`version_number`), '') AS `version_number`,
    TRY_CAST(NULLIF(trim(`width_mm`), '') AS DECIMAL(10,3)) AS `width_mm`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_packaging_spec
)
SELECT *
FROM typed
QUALIFY `packaging_spec_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `packaging_spec_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

