-- product.brand ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_brand (
  CONSTRAINT `brand_id_not_null` EXPECT (`brand_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.brand typed and cleaned, one row per brand_id (latest last_updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    CASE lower(trim(`architecture_type`))
      WHEN 'master_brand' THEN 'master_brand'
      WHEN 'sub_brand' THEN 'sub_brand'
      WHEN 'endorsed_brand' THEN 'endorsed_brand'
      WHEN 'standalone' THEN 'standalone'
      WHEN 'house_of_brands' THEN 'house_of_brands'
      ELSE NULLIF(trim(`architecture_type`), '')
    END AS `architecture_type`,
    CASE lower(trim(`brand_status`))
      WHEN 'active' THEN 'active'
      WHEN 'dormant' THEN 'dormant'
      WHEN 'divested' THEN 'divested'
      WHEN 'discontinued' THEN 'discontinued'
      WHEN 'pipeline' THEN 'pipeline'
      ELSE NULLIF(trim(`brand_status`), '')
    END AS `brand_status`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE lower(trim(`distribution_channel`))
      WHEN 'retail' THEN 'retail'
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'wholesale' THEN 'wholesale'
      WHEN 'dtc' THEN 'dtc'
      WHEN 'dsd' THEN 'dsd'
      WHEN 'omnichannel' THEN 'omnichannel'
      ELSE NULLIF(trim(`distribution_channel`), '')
    END AS `distribution_channel`,
    COALESCE(try_to_date(trim(`divestiture_date`), 'yyyy-MM-dd'), try_to_date(trim(`divestiture_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`divestiture_date`) AS DATE)) AS `divestiture_date`,
    NULLIF(trim(`ean_prefix`), '') AS `ean_prefix`,
    CASE lower(trim(`equity_methodology`))
      WHEN 'nielsen_brand_health' THEN 'nielsen_brand_health'
      WHEN 'kantar_brandz' THEN 'kantar_brandz'
      WHEN 'ipsos_brand_value' THEN 'ipsos_brand_value'
      WHEN 'internal_scorecard' THEN 'internal_scorecard'
      WHEN 'bav' THEN 'bav'
      WHEN 'none' THEN 'none'
      ELSE NULLIF(trim(`equity_methodology`), '')
    END AS `equity_methodology`,
    CASE lower(trim(`geographic_scope`))
      WHEN 'global' THEN 'global'
      WHEN 'regional' THEN 'regional'
      WHEN 'national' THEN 'national'
      WHEN 'local' THEN 'local'
      WHEN 'export_only' THEN 'export_only'
      ELSE NULLIF(trim(`geographic_scope`), '')
    END AS `geographic_scope`,
    NULLIF(trim(`gmp_certification_ref`), '') AS `gmp_certification_ref`,
    CASE WHEN lower(trim(`is_licensed_brand`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_licensed_brand`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_licensed_brand`,
    COALESCE(try_to_timestamp(trim(`last_updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_updated_timestamp`) AS TIMESTAMP)) AS `last_updated_timestamp`,
    COALESCE(try_to_date(trim(`launch_date`), 'yyyy-MM-dd'), try_to_date(trim(`launch_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`launch_date`) AS DATE)) AS `launch_date`,
    TRY_CAST(NULLIF(trim(`launch_year`), '') AS INT) AS `launch_year`,
    COALESCE(try_to_date(trim(`license_expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`license_expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`license_expiry_date`) AS DATE)) AS `license_expiry_date`,
    NULLIF(trim(`msrp_currency_code`), '') AS `msrp_currency_code`,
    NULLIF(trim(`name`), '') AS `name`,
    CASE WHEN lower(trim(`nps_tracking_enabled`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`nps_tracking_enabled`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `nps_tracking_enabled`,
    NULLIF(trim(`owner_division`), '') AS `owner_division`,
    NULLIF(trim(`plm_stage`), '') AS `plm_stage`,
    NULLIF(trim(`positioning_statement`), '') AS `positioning_statement`,
    NULLIF(trim(`primary_category`), '') AS `primary_category`,
    NULLIF(trim(`primary_country_code`), '') AS `primary_country_code`,
    NULLIF(trim(`regulatory_classification`), '') AS `regulatory_classification`,
    NULLIF(trim(`short_name`), '') AS `short_name`,
    NULLIF(trim(`social_media_handle`), '') AS `social_media_handle`,
    NULLIF(trim(`source_system_brand_code`), '') AS `source_system_brand_code`,
    CASE lower(trim(`source_system_code`))
      WHEN 'sap_s4' THEN 'SAP_S4'
      WHEN 'sfdc_cgc' THEN 'SFDC_CGC'
      WHEN 'oracle_erp' THEN 'ORACLE_ERP'
      WHEN 'veeva' THEN 'VEEVA'
      WHEN 'manual' THEN 'MANUAL'
      ELSE NULLIF(trim(`source_system_code`), '')
    END AS `source_system_code`,
    CASE lower(trim(`sustainability_certification`))
      WHEN 'fsc' THEN 'fsc'
      WHEN 'rspo' THEN 'rspo'
      WHEN 'iso_14001' THEN 'iso_14001'
      WHEN 'rainforest_alliance' THEN 'rainforest_alliance'
      WHEN 'none' THEN 'none'
      WHEN 'multiple' THEN 'multiple'
      ELSE NULLIF(trim(`sustainability_certification`), '')
    END AS `sustainability_certification`,
    NULLIF(trim(`target_consumer_segment`), '') AS `target_consumer_segment`,
    CASE lower(trim(`tier`))
      WHEN 'premium' THEN 'premium'
      WHEN 'mass' THEN 'mass'
      WHEN 'value' THEN 'value'
      WHEN 'super_premium' THEN 'super_premium'
      WHEN 'private_label' THEN 'private_label'
      ELSE NULLIF(trim(`tier`), '')
    END AS `tier`,
    CASE WHEN lower(trim(`trade_promotion_eligible`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`trade_promotion_eligible`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `trade_promotion_eligible`,
    NULLIF(trim(`trademark_jurisdiction`), '') AS `trademark_jurisdiction`,
    NULLIF(trim(`trademark_registration_ref`), '') AS `trademark_registration_ref`,
    NULLIF(trim(`website_url`), '') AS `website_url`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_brand
)
SELECT *
FROM typed
QUALIFY `brand_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `brand_id` ORDER BY `last_updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

