    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`effective_until`), 'yyyy-MM-dd'), try_to_date(trim(`effective_until`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_until`) AS DATE)) AS `effective_until`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    CASE WHEN lower(trim(`hazardous_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazardous_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazardous_flag`,
    COALESCE(try_to_timestamp(trim(`last_updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_updated_timestamp`) AS TIMESTAMP)) AS `last_updated_timestamp`,
    NULLIF(trim(`lifecycle_stage`), '') AS `lifecycle_stage`,
    NULLIF(trim(`material_group`), '') AS `material_group`,
    NULLIF(trim(`material_status`), '') AS `material_status`,
    NULLIF(trim(`material_type`), '') AS `material_type`,
    NULLIF(trim(`name`), '') AS `name`,
    NULLIF(trim(`packaging_type`), '') AS `packaging_type`,
    NULLIF(trim(`regulatory_status`), '') AS `regulatory_status`,
    TRY_CAST(NULLIF(trim(`shelf_life_days`), '') AS INT) AS `shelf_life_days`,
    TRY_CAST(NULLIF(trim(`standard_cost`), '') AS DECIMAL(12,4)) AS `standard_cost`,
    TRY_CAST(NULLIF(trim(`storage_temperature_c`), '') AS DECIMAL(5,2)) AS `storage_temperature_c`,
    TRY_CAST(NULLIF(trim(`unit_conversion_factor`), '') AS DECIMAL(12,6)) AS `unit_conversion_factor`,
    NULLIF(trim(`upc`), '') AS `upc`,
    TRY_CAST(NULLIF(trim(`volume_l`), '') AS DECIMAL(10,3)) AS `volume_l`,
    TRY_CAST(NULLIF(trim(`weight_kg`), '') AS DECIMAL(10,3)) AS `weight_kg`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_material
)
SELECT *
FROM typed
QUALIFY `material_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `material_id` ORDER BY `last_updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- product.category ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.product_category (
  CONSTRAINT `category_id_not_null` EXPECT (`category_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: product.category typed and cleaned, one row per category_id (latest _ingested_at wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`category_id`), '') AS BIGINT) AS `category_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.product_category
)
SELECT *
FROM typed
QUALIFY `category_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `category_id` ORDER BY _ingested_at DESC) = 1;
